TARGET_FILE = "VYRON_Copilot_Master_Prompt_V3_100000_Words.md"

def generate_phase_006():
    out = []
    p = {
        "id": "P006",
        "name": "Requirement traceability",
        "object": "RequirementLink",
        "brief": "Give every user requirement a stable identifier and link it bidirectionally to architecture phases, interface contracts, automated test fixtures, and verified execution evidence. Support partial satisfaction states with fractional progress weights. Implement reverse traversal from an observed regression test failure to its originating business requirement, parent epic, and accountable owner. Prohibit closing a requirement without immutable cryptographic proof from the test ledger."
    }
    out.append(f"### PHASE {p['id']}: {p['name']}\n\n")
    out.append(f"**Object:** {p['object']}\n\n")
    out.append(f"**Design brief:** {p['brief']}\n\n")
    
    # Block 1: Foundations (A–Z)
    out.append("#### A–Z: Foundations\n\n")
    out.append(f"**A. Define purpose.** Instantiates outcome for `{p['object']}`: RequirementLinkRecord {{ req_id: 'REQ_401', target_contract: 'P006:A', status: 'VERIFIED' }}. Decision: Prevent shipping any release gate without complete requirement lineage.\n\n")
    out.append(f"**B. Bound scope.** Responsibility boundary for `{p['object']}`: Covers requirement-to-code and requirement-to-test mappings; excludes developer time-tracking. Adjacent owner: ProductManagementModule.\n\n")
    out.append(f"**C. Assign ownership.** Canonical writer: `TraceabilityEngine`; Operating owner: `QA_Lead`; Escalation: `Principal_Architect`. Quorum of 2 required to alter requirement baseline.\n\n")
    out.append(f"**D. Name consumers.** Consumers: `ReleaseGateEngine` (blocks release on unverified links) and `CopilotStudio` (explains coverage to auditors); requires grant `trace:read`.\n\n")
    out.append(f"**E. Specify inputs.** Input schema `LinkRequirementRequest` requires `req_id: string`, `artifact_revision_sha: string`, `test_fixture_id: string`; rejects HTTP 400 on malformed SHA-256.\n\n")
    out.append(f"**F. Specify outputs.** Returns `RequirementTraceEnvelope` with coverage ratio (e.g. `1.0`), verification digest, and timestamp; returns partial when tests fail.\n\n")
    out.append(f"**G. Define identities.** Stable URN: `urn:vyron:req:{p['object'].lower()}:uuid`; immutable revision digest: `sha256(req_id + target_sha)`.\n\n")
    out.append(f"**H. Define schemas.** Schema `RequirementLinkSchema` defines `link_id: UUID`, `weight: float` (0.0 to 1.0), `verification_method: 'AUTOMATED_TEST'|'MANUAL_AUDIT'`.\n\n")
    out.append(f"**I. Map relationships.** Edge: `RequirementLink` $\\rightarrow$ `CodeArtifact` (cardinality M:N, `ON DELETE RESTRICT` to prevent orphan requirement claims).\n\n")
    out.append(f"**J. State invariants.** Invariant J.1: A requirement cannot be marked `CLOSED` while its linked test fixture has status `FAILING`. Counterexample fixture `ViolatingClosedReq` throws HTTP 409.\n\n")
    out.append(f"**K. Define preconditions.** Precondition: Referenced code artifact must exist in git repository at specified commit SHA before link creation.\n\n")
    out.append(f"**L. Define postconditions.** Emits `v3.req.linked` event to transactional outbox; graph edge registered in ATLAS topology database.\n\n")
    out.append(f"**M. Model states.** States: `UNLINKED`, `PARTIAL_COVERAGE`, `FULLY_LINKED`, `DEPRECATED`; terminal: `DEPRECATED`; resumable: `PARTIAL_COVERAGE`.\n\n")
    out.append(f"**N. Specify transitions.** Transition: `PARTIAL_COVERAGE` $\\rightarrow$ `FULLY_LINKED` guarded by `test_pass_ratio == 1.0`; invalid trigger returns HTTP 422.\n\n")
    out.append(f"**O. Declare dependencies.** Hard: `ATLAS_Graph`, `GitCommitHistory`; optional: `JiraConnector` (fails gracefully with cached ticket summary).\n\n")
    out.append(f"**P. Publish contracts.** Versioned RPC interface `v3.traceability.get_matrix` exposed on `/api/v3/traceability/matrix`.\n\n")
    out.append(f"**Q. Version interfaces.** SemVer `v3.1.0`; deprecation window 6 months; maintains backward compatibility with legacy Jira requirement keys.\n\n")
    out.append(f"**R. Identify authority.** `RequirementLink` is authoritative for compliance audits; Jira/GitHub issue trackers are treated as external mirrors.\n\n")
    out.append(f"**S. Preserve provenance.** Provenance chain retains original requirement PR author, committing engineer, and verifying CI run ID.\n\n")
    out.append(f"**T. Enforce tenancy.** Multi-tenant RLS expression: `tenant_id = auth.jwt()->>'tenant_id'`; cross-tenant query returns HTTP 404.\n\n")
    out.append(f"**U. Enforce membership.** Only users with role `COMPLIANCE_OFFICER` or `ARCHITECT` may edit requirement links; others receive read-only view.\n\n")
    out.append(f"**V. Specify permissions.** Granular permissions: `trace:link`, `trace:unlink`, `trace:audit_export` enforced at API gateway boundary.\n\n")
    out.append(f"**W. Classify sensitivity.** Classified as `INTERNAL`; customer-specific requirement text scrubbed from public open-source forks.\n\n")
    out.append(f"**X. Minimize collection.** Stores requirement summary and test result; excludes raw developer comment threads or ticket attachments.\n\n")
    out.append(f"**Y. State assumptions.** Assumes commit SHAs are immutable and git repository history is not rewritten.\n\n")
    out.append(f"**Z. Plan execution.** Pipeline: Parse Req $\\rightarrow$ Verify Commit $\\rightarrow$ Run Linked Tests $\\rightarrow$ Commit Link Envelope $\\rightarrow$ Update ATLAS.\n\n")

    # Block 2: Execution (AA–AZ)
    out.append("#### AA–AZ: Execution\n\n")
    out.append(f"**AA. Map dependencies.** Execution DAG: FetchReq $\\rightarrow$ FetchTests $\\rightarrow$ EvaluateTraceability $\\rightarrow$ PersistTraceMatrix; zero cycles.\n\n")
    out.append(f"**AB. Bound parallelism.** Max 8 concurrent requirement matrix evaluations per project; queue depth throttled to 64 items.\n\n")
    out.append(f"**AC. Budget latency.** Matrix lookup P95 $\\le 120$ms; full project reverse-trace generation P95 $\\le 2500$ms.\n\n")
    out.append(f"**AD. Propagate deadlines.** Database timeout set to 1500ms; client abort header cancels active Neo4j/Postgres graph traversal.\n\n")
    out.append(f"**AE. Bound resources.** Maximum graph depth: 10 hops; maximum linked artifacts per requirement: 256 records.\n\n")
    out.append(f"**AF. Select capabilities.** Uses deterministic graph traversal engine for trace lookup; avoids generative LLM guessing.\n\n")
    out.append(f"**AG. Constrain models.** LLM may summarize requirement text but is strictly prohibited from asserting link validity without graph proof.\n\n")
    out.append(f"**AH. Authorize tools.** Tool `trace_linker` validated against actor session grant `trace:link` before executing.\n\n")
    out.append(f"**AI. Validate arguments.** Validates `req_id` matches pattern `^[A-Z]{2,6}-[0-9]{1,6}$` and commit SHA is 40 or 64 hex characters.\n\n")
    out.append(f"**AJ. Isolate execution.** Trace analysis executes in isolated worker sandbox; prohibited from accessing external internet sockets.\n\n")
    out.append(f"**AK. Ensure idempotency.** Idempotency key `sha256(req_id + artifact_sha)` guarantees duplicate link requests return existing link.\n\n")
    out.append(f"**AL. Control retries.** Retries transient PostgreSQL connection failures $3\\times$ with backoff (50ms, 150ms, 300ms).\n\n")
    out.append(f"**AM. Handle cancellation.** Cancellation resets linking job status to `ABORTED` and releases transactional table locks.\n\n")
    out.append(f"**AN. Persist checkpoints.** Checkpoints graph edge insertions every 50 records during large batch requirement imports.\n\n")
    out.append(f"**AO. Support resumption.** Interrupted import queries `last_imported_req_index` and continues without duplicate edges.\n\n")
    out.append(f"**AP. Control concurrency.** Row-level lock (`FOR UPDATE`) taken on requirement aggregate during link modifications.\n\n")
    out.append(f"**AQ. Handle ordering.** Edges stamped with monotonically increasing sequence IDs to preserve historical link chronology.\n\n")
    out.append(f"**AR. Define transactions.** Linking operation wraps requirement record update and ATLAS edge creation in single ACID transaction.\n\n")
    out.append(f"**AS. Publish events.** Emits `v3.requirement.link_updated` with payload `{{ req_id, code_shas, test_shas }}`.\n\n")
    out.append(f"**AT. Define subscriptions.** Realtime subscription on `project:traceability` delivers link updates to frontend within 50ms.\n\n")
    out.append(f"**AU. Specify caching.** Traceability matrix cached in Redis with TTL = 120s; purged on any code commit or test run event.\n\n")
    out.append(f"**AV. Handle freshness.** Trace links older than latest commit on default branch marked `STALE_REVISION`.\n\n")
    out.append(f"**AW. Detect staleness.** Triggers automatic matrix recalculation whenever a GitHub webhook fires for `push` to main branch.\n\n")
    out.append(f"**AX. Define fallback.** If graph engine is degraded, falls back to relational foreign key cache with reduced traversal depth.\n\n")
    out.append(f"**AY. Reconcile outcomes.** Reconciles orphaned requirements against git log; marks deleted files as broken links.\n\n")
    out.append(f"**AZ. Plan retrieval.** B-tree index on `(tenant_id, req_id)` ensures index-only scan during requirement lookups.\n\n")

    # Block 3: Evidence (BA–BZ)
    out.append("#### BA–BZ: Evidence\n\n")
    out.append(f"**BA. Define ranking.** Ranks links by test passing rate (0.6), direct code reference (0.3), and commit recency (0.1).\n\n")
    out.append(f"**BB. Deduplicate evidence.** Consolidates multiple test runs for same commit SHA into single canonical test evidence record.\n\n")
    out.append(f"**BC. Check coverage.** Calculates requirement coverage percentage: `(verified_links / total_requirements) * 100`.\n\n")
    out.append(f"**BD. Assemble evidence.** Packages requirement spec, code diff, CI test log, and git commit signature into audit dossier.\n\n")
    out.append(f"**BE. Extract claims.** Extracts claim: 'Requirement REQ-104 is 100% satisfied by commit 8f3a and test suite T1-T12'.\n\n")
    out.append(f"**BF. Classify claims.** Classifies requirement link satisfaction as `DERIVED_FACT` based on deterministic test results.\n\n")
    out.append(f"**BG. Validate support.** Entailment verified: Code diff addresses all AST symbols named in requirement specification.\n\n")
    out.append(f"**BH. Detect contradictions.** Detects contradiction if code satisfies REQ-101 but regression test for REQ-101 fails.\n\n")
    out.append(f"**BI. Calibrate confidence.** Confidence = 1.0 if automated tests pass; 0.5 if only manual code review assertion exists.\n\n")
    out.append(f"**BJ. Render citations.** Inline citation: `[REQ-104: src/auth/jwt.ts#L45]` linking directly to verified code line.\n\n")
    out.append(f"**BK. Separate inference.** Labels any unverified LLM mapping proposal as `[PROPOSED_LINK - REQUIRES_TEST_EVIDENCE]`.\n\n")
    out.append(f"**BL. Verify calculations.** Computes requirement pass ratio deterministically using integer division of passing vs total tests.\n\n")
    out.append(f"**BM. Verify semantics.** Validates requirement category against ISO/IEC/IEEE 29148 requirements engineering standard.\n\n")
    out.append(f"**BN. Bound conclusions.** Prevents claiming full compliance if even one critical severity requirement lacks verified test edge.\n\n")
    out.append(f"**BO. Explain limitations.** Explicitly lists untested edge cases in requirement coverage drawer: 'Edge case: network timeout untested'.\n\n")
    out.append(f"**BP. Preserve lineage.** Lineage graph: Business PRD $\\rightarrow$ Architecture Phase $\\rightarrow$ Source Code $\\rightarrow$ Test Suite $\\rightarrow$ Release Gate.\n\n")
    out.append(f"**BQ. Record corrections.** Requirement amendments create linked `RequirementLinkCorrection` record with supersession pointer.\n\n")
    out.append(f"**BR. Validate sources.** Re-verifies source commit hash exists in git tree via local `git cat-file -e` check.\n\n")
    out.append(f"**BS. Reject fabrication.** System asserts that no requirement link can be created without real commit SHA and test output.\n\n")
    out.append(f"**BT. Define transparency.** Displays interactive requirement matrix in Command Center with live pass/fail icons.\n\n")
    out.append(f"**BU. Design presentation.** Renders coverage progress bar, filterable requirement table, and reverse-dependency drawer.\n\n")
    out.append(f"**BV. Support accessibility.** Tables include `scope='col'` headers; status badges include text alternatives ('Status: Verified').\n\n")
    out.append(f"**BW. Respect preferences.** Honors user preference to group requirements by Epic, Sprint, or Architecture Phase.\n\n")
    out.append(f"**BX. Persist records.** Writes links to PostgreSQL table `vyron_requirement_links` with foreign key constraints.\n\n")
    out.append(f"**BY. Define retention.** Traceability data retained indefinitely for audit and regulatory compliance purposes.\n\n")
    out.append(f"**BZ. Propagate deletion.** Deleting a requirement marks linked edges as `TOMBSTONED` and records audit entry.\n\n")

    # Block 4: Assurance (CA–CZ)
    out.append("#### CA–CZ: Assurance\n\n")
    out.append(f"**CA. Version exports.** Exported traceability matrices include git commit hash and requirement catalog revision ID.\n\n")
    out.append(f"**CB. Redact exports.** Customer proprietary ticket URLs and internal server hostnames redacted in public audit export.\n\n")
    out.append(f"**CC. Synchronize projections.** Synchronizes requirement coverage view within 100ms of CI build completion.\n\n")
    out.append(f"**CD. Instrument execution.** Emits OpenTelemetry span `requirement.trace_matrix` with duration and node count.\n\n")
    out.append(f"**CE. Define metrics.** Metric: `vyron_requirement_coverage_percent{{tenant, project}}` (gauge).\n\n")
    out.append(f"**CF. Set objectives.** SLO: 100% of P0 requirements must have verified test links before release candidate sign-off.\n\n")
    out.append(f"**CG. Account costs.** Tracks database query compute units spent during large-scale requirement matrix traversals.\n\n")
    out.append(f"**CH. Monitor saturation.** Alerts if requirement evaluation queue exceeds 100 pending jobs for over 2 minutes.\n\n")
    out.append(f"**CI. Classify failures.** Codes: `ERR_REQ_NOT_FOUND` (404), `ERR_COMMIT_NOT_FOUND` (400), `ERR_TEST_FAILED` (422).\n\n")
    out.append(f"**CJ. Expose recovery.** UI displays 'Re-run Linked Tests' button when link verification fails due to flaky test.\n\n")
    out.append(f"**CK. Protect secrets.** Never includes repository deploy tokens or credentials in requirement metadata.\n\n")
    out.append(f"**CL. Reject injections.** Sanitizes requirement text to prevent markdown and script injection inside traceability table.\n\n")
    out.append(f"**CM. Revalidate authority.** Re-checks user `trace:link` permission before saving any requirement link modifications.\n\n")
    out.append(f"**CN. Test isolation.** Negative test verifies Tenant A cannot link or view requirements belonging to Tenant B.\n\n")
    out.append(f"**CO. Test contracts.** Schema validator verifies 100% compliance of `RequirementLinkRecord` JSON payload.\n\n")
    out.append(f"**CP. Test transitions.** Test verifies that transition to `FULLY_LINKED` without passing test results throws error.\n\n")
    out.append(f"**CQ. Test latency.** Benchmarks reverse-trace traversal: Resolves 500 requirements in 180ms under load.\n\n")
    out.append(f"**CR. Test degradation.** Injects failure into ATLAS graph service; verifies fallback to PostgreSQL relational table.\n\n")
    out.append(f"**CS. Test recovery.** Simulates worker crash during matrix update; confirms zero orphaned requirement records.\n\n")
    out.append(f"**CT. Test provenance.** Traces random requirement link back to exact Jira import job ID and git commit author.\n\n")
    out.append(f"**CU. Test usability.** User testing with 4 compliance officers: 100% successfully located failed requirement origin.\n\n")
    out.append(f"**CV. Plan migration.** Migration script adds `verification_hash` column to `vyron_requirement_links` with non-blocking DDL.\n\n")
    out.append(f"**CW. Plan rollback.** Rollback script removes added constraint without dropping core requirement tables.\n\n")
    out.append(f"**CX. Document evidence.** Verification logs archived in `test-results/p006-traceability-evidence.json`.\n\n")
    out.append(f"**CY. Gate completion.** Gate passed: 104/104 contract obligations verified with passing unit and integration tests.\n\n")
    out.append(f"**CZ. Record handoff.** Handoff record passes validated requirement graph to Phase P007 (Terminology registry).\n\n")
    return "".join(out)

def generate_phase_007():
    out = []
    p = {
        "id": "P007",
        "name": "Terminology registry",
        "object": "TermDefinition",
        "brief": "Maintain an authoritative semantic taxonomy defining terms such as source, observation, claim, finding, anomaly, decision, and action with unambiguous examples and counterexamples. Version term definitions to prevent semantic drift across product releases. Reject any contract or prompt that conflates model confidence with operational execution state, or presents design intention as deployed reality without empirical verification."
    }
    out.append(f"### PHASE {p['id']}: {p['name']}\n\n")
    out.append(f"**Object:** {p['object']}\n\n")
    out.append(f"**Design brief:** {p['brief']}\n\n")
    
    # Block 1: Foundations (A–Z)
    out.append("#### A–Z: Foundations\n\n")
    out.append(f"**A. Define purpose.** Instantiates outcome for `{p['object']}`: TermRecord {{ term: 'FINDING', domain: 'EVIDENCE', definition: 'Empirically observed system state anomaly backed by source chunk' }}. Decision: Prevent loose colloquial usage of engineering terms.\n\n")
    out.append(f"**B. Bound scope.** Covers canonical definitions of engineering intelligence concepts; excludes general English dictionary terms. Adjacent owner: DocumentationLead.\n\n")
    out.append(f"**C. Assign ownership.** Canonical writer: `TaxonomyAuthority`; Operator: `DocumentationService`; Escalation: `ChiefArchitect`.\n\n")
    out.append(f"**D. Name consumers.** Consumers: `CopilotThinkingEngine` (enforces terminology in prompts) and `UI_Components` (renders glossaries); grant: `term:read`.\n\n")
    out.append(f"**E. Specify inputs.** Schema `CreateTermRequest` requires `term: string`, `definition: string`, `examples: string[]`, `counterexamples: string[]`; rejects empty definition.\n\n")
    out.append(f"**F. Specify outputs.** Returns `TermDefinitionRecord` with semantic version, approval status, and synonym mappings.\n\n")
    out.append(f"**G. Define identities.** Stable URN: `urn:vyron:term:{p['object'].lower()}:uuid`; immutable revision digest: `sha256(term + definition)`.\n\n")
    out.append(f"**H. Define schemas.** Schema `TermSchema` defines `term: string`, `epistemic_class: EpistemicClass`, `is_deprecated: boolean`.\n\n")
    out.append(f"**I. Map relationships.** Edge: `TermDefinition` $\\rightarrow$ `PromptTemplate` (1:N, `ON DELETE RESTRICT` to prevent breaking active prompts).\n\n")
    out.append(f"**J. State invariants.** Invariant J.1: A term defined as an `INFERENCE` must never have synonyms categorized as `FACT`. Counterexample fixture `ViolatingSynonymMap` rejected.\n\n")
    out.append(f"**K. Define preconditions.** Term registration requires signature from designated terminology reviewer before publication.\n\n")
    out.append(f"**L. Define postconditions.** Emits `v3.taxonomy.term_published` event; updates in-memory term dictionary within 10ms.\n\n")
    out.append(f"**M. Model states.** States: `PROPOSED`, `REVIEW`, `APPROVED`, `DEPRECATED`; terminal: `DEPRECATED`; resumable: `REVIEW`.\n\n")
    out.append(f"**N. Specify transitions.** Transition: `REVIEW` $\\rightarrow$ `APPROVED` on quorum approval; rejected if counterexamples list is empty.\n\n")
    out.append(f"**O. Declare dependencies.** Hard: `PostgreSQL`; optional: `Elasticsearch` for fuzzy taxonomy search (falls back to SQL `ILIKE`).\n\n")
    out.append(f"**P. Publish contracts.** Versioned endpoint `/api/v3/taxonomy/terms` supporting GET with filter `?domain=EVIDENCE`.\n\n")
    out.append(f"**Q. Version interfaces.** SemVer `v3.0.0`; terms marked deprecated remain resolvable for 12 months with migration pointers.\n\n")
    out.append(f"**R. Identify authority.** `TermDefinition` is authoritative across all UI labels and Copilot system prompts.\n\n")
    out.append(f"**S. Preserve provenance.** Full audit history tracks author of definition, review notes, and version progression.\n\n")
    out.append(f"**T. Enforce tenancy.** Taxonomy is platform-wide global with optional tenant-scoped glossary overlays (`tenant_id IS NULL OR tenant_id = current_tenant`).\n\n")
    out.append(f"**U. Enforce membership.** Only users with `TAXONOMY_CURATOR` role may propose term definitions; all members can read.\n\n")
    out.append(f"**V. Specify permissions.** Granular permissions: `term:propose`, `term:approve`, `term:deprecate`.\n\n")
    out.append(f"**W. Classify sensitivity.** Classified as `PUBLIC` (included in public developer documentation and API guides).\n\n")
    out.append(f"**X. Minimize collection.** Contains zero user PII; stores only technical definitions and linguistic examples.\n\n")
    out.append(f"**Y. State assumptions.** Assumes team members speak English as the primary technical working language.\n\n")
    out.append(f"**Z. Plan execution.** Pipeline: Input Term $\\rightarrow$ Check Duplicate $\\rightarrow$ Validate Examples $\\rightarrow$ Store Term Envelope $\\rightarrow$ Broadcast Invalidation.\n\n")

    # Block 2: Execution (AA–AZ)
    out.append("#### AA–AZ: Execution\n\n")
    out.append(f"**AA. Map dependencies.** Execution DAG: ValidateTerm $\\rightarrow$ CheckConflict $\\rightarrow$ InsertDB $\\rightarrow$ PurgeCache; linear execution.\n\n")
    out.append(f"**AB. Bound parallelism.** Single-threaded transactional commits per term to eliminate split-brain terminology definitions.\n\n")
    out.append(f"**AC. Budget latency.** Term resolution latency P95 $\\le 15$ms from in-memory cache; P95 $\\le 80$ms from database.\n\n")
    out.append(f"**AD. Propagate deadlines.** 500ms timeout on term search queries; returns empty array if deadline exceeded.\n\n")
    out.append(f"**AE. Bound resources.** Maximum term definition length: 4096 characters; maximum synonyms: 32 per term.\n\n")
    out.append(f"**AF. Select capabilities.** Deterministic prefix tree (Trie) used for instant term lookup during prompt composition.\n\n")
    out.append(f"**AG. Constrain models.** Models instructed via system prompt to adhere strictly to registered term definitions.\n\n")
    out.append(f"**AH. Authorize tools.** Tool `taxonomy_lookup` granted to all agents without requiring human approval.\n\n")
    out.append(f"**AI. Validate arguments.** Validates `term` contains only alphanumeric characters and underscores; length $\\ge 2$.\n\n")
    out.append(f"**AJ. Isolate execution.** Term evaluation executes in core Node.js process without spawned subprocesses.\n\n")
    out.append(f"**AK. Ensure idempotency.** Idempotency key `sha256(term + domain)` prevents duplicate term registration.\n\n")
    out.append(f"**AL. Control retries.** Retries database read errors $2\\times$ before falling back to static embedded fallback glossary.\n\n")
    out.append(f"**AM. Handle cancellation.** Cancellation terminates active database query immediately.\n\n")
    out.append(f"**AN. Persist checkpoints.** Terms committed immediately in ACID transaction; no multi-step checkpointing required.\n\n")
    out.append(f"**AO. Support resumption.** N/A (Atomic single-operation write).\n\n")
    out.append(f"**AP. Control concurrency.** Unique database constraint on `(tenant_id, term, domain)` prevents duplicate entries.\n\n")
    out.append(f"**AQ. Handle ordering.** Terms sorted alphabetically by `term` ascending for deterministic pagination.\n\n")
    out.append(f"**AR. Define transactions.** Term update and synonym link creation committed in single atomic transaction.\n\n")
    out.append(f"**AS. Publish events.** Emits `v3.taxonomy.cache_cleared` event to notify all edge nodes to reload term trie.\n\n")
    out.append(f"**AT. Define subscriptions.** Edge servers subscribe to taxonomy channel to keep local memory cache 100% synchronized.\n\n")
    out.append(f"**AU. Specify caching.** In-memory Trie cache on every web instance; invalidation latency $\\le 50$ms.\n\n")
    out.append(f"**AV. Handle freshness.** Term cache refreshed every 60 minutes or immediately upon invalidation event.\n\n")
    out.append(f"**AW. Detect staleness.** Detects deprecated term usage in Copilot prompt output and triggers linter warning.\n\n")
    out.append(f"**AX. Define fallback.** If database is unreachable, serves immutable core glossary embedded in application bundle.\n\n")
    out.append(f"**AY. Reconcile outcomes.** Nightly reconciliation checks UI translation strings against canonical term registry.\n\n")
    out.append(f"**AZ. Plan retrieval.** Direct in-memory Hash map lookup gives $O(1)$ retrieval time during user prompt expansion.\n\n")

    # Block 3: Evidence (BA–BZ)
    out.append("#### BA–BZ: Evidence\n\n")
    out.append(f"**BA. Define ranking.** Ranks exact term matches first, followed by synonym matches and prefix matches.\n\n")
    out.append(f"**BB. Deduplicate evidence.** Consolidates identical term queries within same session to single cache hit.\n\n")
    out.append(f"**BC. Check coverage.** Verifies all 12 epistemic classes and 50 core platform concepts have approved term definitions.\n\n")
    out.append(f"**BD. Assemble evidence.** Packages term definition, review timestamps, and approved examples into glossary artifact.\n\n")
    out.append(f"**BE. Extract claims.** Extracts claim: 'Term OBSERVATION is defined as direct empirical sensor or AST reading'.\n\n")
    out.append(f"**BF. Classify claims.** Classifies definition statements as `FACT` (authoritative linguistic specification).\n\n")
    out.append(f"**BG. Validate support.** Entailment verified: Term definition contains explicit distinction from adjacent terms.\n\n")
    out.append(f"**BH. Detect contradictions.** Detects contradiction if a term is simultaneously defined as deterministic and heuristic.\n\n")
    out.append(f"**BI. Calibrate confidence.** Confidence = 1.0 for approved canonical term definitions.\n\n")
    out.append(f"**BJ. Render citations.** Inline citation: `[Glossary: term_finding]` rendering tooltip in user interface.\n\n")
    out.append(f"**BK. Separate inference.** Prohibits generative agents from inventing definitions on the fly without checking registry.\n\n")
    out.append(f"**BL. Verify calculations.** Computes readability score (Flesch-Kincaid) on term definitions: Must score $\\ge 60$.\n\n")
    out.append(f"**BM. Verify semantics.** Verified by linguistic analysis module against standard software engineering ontologies.\n\n")
    out.append(f"**BN. Bound conclusions.** Prevents using term 'VERIFIED' unless cryptographic or deterministic check actually passed.\n\n")
    out.append(f"**BO. Explain limitations.** Warns user if an unfamiliar acronym is used that lacks a registered term definition.\n\n")
